mapper.select:
SELECT * FROM ( SELECT a.*, ROW_NUMBER() OVER (ORDER BY TO_DATE(a.schdul_date, 'YYYY-MM-DD') DESC, a.attend ASC NULLS FIRST) AS rnum FROM ( SELECT s.schdul_no, TO_CHAR(s.schdul_date, 'YYYY-MM-DD') as schdul_date, s.user_no, s.attend, s.leave, s.working_time, s.status, u.user_nm, d.dept_nm, p.position_nm FROM schedule s INNER JOIN tb_user u ON s.user_no = u.user_no INNER JOIN employee e ON u.user_no = e.user_no INNER JOIN dept d ON e.dept_no = d.dept_no INNER JOIN position p ON e.position_no = p.position_no WHERE d.dept_nm IS NOT NULL AND d.dept_state = 1 AND p.position_nm IS NOT NULL AND e.dept_no IS NOT NULL AND e.position_no IS NOT NULL
AND TO_CHAR(s.schdul_date, 'YYYY-MM') = #{searchDate}
AND d.dept_nm = #{deptNm}
AND s.status = #{status}
) a ) b WHERE rnum BETWEEN (#{page} - 1) * #{size} + 1 AND #{page} * #{size}

SELECT d.dept_nm, COUNT(*) as total_records, SUM(CASE WHEN s.status = '정상' THEN 1 ELSE 0 END) as normal_count, SUM(CASE WHEN s.status = '지각' THEN 1 ELSE 0 END) as late_count, SUM(CASE WHEN s.status = '조기퇴근' THEN 1 ELSE 0 END) as early_leave_count, ROUND(AVG( TO_NUMBER(SUBSTR(s.working_time, 1, 2)) + TO_NUMBER(SUBSTR(s.working_time, 4, 2)) / 60 ), 1) as avg_working_hours FROM schedule s INNER JOIN tb_user u ON s.user_no = u.user_no INNER JOIN employee e ON u.user_no = e.user_no INNER JOIN dept d ON e.dept_no = d.dept_no INNER JOIN position p ON e.position_no = p.position_no WHERE d.dept_nm IS NOT NULL AND d.dept_state = 1 AND e.dept_no IS NOT NULL AND e.position_no IS NOT NULL AND p.position_nm IS NOT NULL AND TO_CHAR(s.schdul_date, 'YYYY-MM') = #{searchDate}
AND d.dept_nm = #{deptNm}
GROUP BY d.dept_nm ORDER BY d.dept_nm

SELECT COUNT(*) FROM schedule s INNER JOIN tb_user u ON s.user_no = u.user_no INNER JOIN employee e ON u.user_no = e.user_no INNER JOIN dept d ON e.dept_no = d.dept_no INNER JOIN position p ON e.position_no = p.position_no WHERE d.dept_nm IS NOT NULL AND d.dept_state = 1 AND e.dept_no IS NOT NULL AND e.position_no IS NOT NULL AND p.position_nm IS NOT NULL
AND TO_CHAR(s.schdul_date, 'YYYY-MM') = #{searchDate}
AND d.dept_nm = #{deptNm}
AND s.status = #{status}
